import React from "react";
import { useNavigate } from "react-router-dom";

function WelcomePage() {
  const navigate = useNavigate();

  const handleGetStarted = () => {
    navigate("/login");
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 p-6">
      <div className="max-w-2xl text-center mb-12">
        <h1 className="text-5xl font-bold text-white mb-6">Secure E-Diary</h1>
        <p className="text-xl text-indigo-100 mb-8">
          Your private, encrypted digital journal for thoughts, memories, and important information
        </p>
        <button
          onClick={handleGetStarted}
          className="px-10 py-4 bg-white text-purple-700 font-bold text-xl rounded-full shadow-lg hover:bg-indigo-100 transform hover:scale-105 transition-all duration-300"
        >
          Get Started
        </button>
      </div>
      
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-4xl w-full">
        <div className="bg-white bg-opacity-20 backdrop-blur-sm p-6 rounded-2xl text-white">
          <h3 className="font-bold text-lg mb-2">End-to-End Encryption</h3>
          <p className="text-indigo-100">Military-grade security for all your entries</p>
        </div>
        <div className="bg-white bg-opacity-20 backdrop-blur-sm p-6 rounded-2xl text-white">
          <h3 className="font-bold text-lg mb-2">Personalized Experience</h3>
          <p className="text-indigo-100">Customize based on your role and needs</p>
        </div>
        <div className="bg-white bg-opacity-20 backdrop-blur-sm p-6 rounded-2xl text-white">
          <h3 className="font-bold text-lg mb-2">Multiple Login Options</h3>
          <p className="text-indigo-100">Password, PIN, or voice authentication</p>
        </div>
      </div>
    </div>
  );
}

export default WelcomePage;
